-- 비상교육 초5 영어 Lesson 1 (Where Are You From?) 콘텐츠: 문항(초안) · 단어 · 핵심 표현 · 교과서 QR 스크립트 · 영상 장면 이미지 프롬프트 · 단어 그림 프롬프트
-- Lesson 1 흐름(6차시)은 admin 에 이미 있으므로 건드리지 않는다. 문항은 모두 초안(draft)으로 들어간다 (승인·발행은 따로). content/l1 에서 생성.
do $do$
declare v_unit uuid; v_cnt int; v_n int; v_miss int; v_style uuid; v_src uuid;
begin
  select count(*), min(u.id::text)::uuid into v_cnt, v_unit from units u join books b on b.id = u.book_id left join publishers pb on pb.id = b.publisher_id where u.no = 1 and u.kind = 'lesson' and b.grade = 5 and (pb.name like '%비상%' or b.title like '%비상%');
  if v_cnt <> 1 then raise exception 'L1 unit lookup: % match(es)', v_cnt; end if;
  if exists (select 1 from items where unit_id = v_unit) then raise exception 'L1 already has items - refusing to overwrite'; end if;

  -- 단어(나라 이름)와 핵심 표현
  insert into vocab(key, en, ko) select x.key, x.en, x.ko from jsonb_to_recordset($j$[{"key":"brazil","en":"Brazil","ko":"브라질"},{"key":"egypt","en":"Egypt","ko":"이집트"},{"key":"france","en":"France","ko":"프랑스"},{"key":"korea","en":"Korea","ko":"한국"},{"key":"thailand","en":"Thailand","ko":"태국"},{"key":"us","en":"U.S.","ko":"미국"}]$j$::jsonb) as x(key text, en text, ko text)
    on conflict (key) do update set en = excluded.en, ko = excluded.ko;
  insert into unit_vocab(unit_id, vocab_id) select v_unit, v.id from vocab v where v.key in (select key from jsonb_to_recordset($j$[{"key":"brazil","en":"Brazil","ko":"브라질"},{"key":"egypt","en":"Egypt","ko":"이집트"},{"key":"france","en":"France","ko":"프랑스"},{"key":"korea","en":"Korea","ko":"한국"},{"key":"thailand","en":"Thailand","ko":"태국"},{"key":"us","en":"U.S.","ko":"미국"}]$j$::jsonb) as x(key text)) on conflict do nothing;
  insert into expressions(en, ko) select x.en, x.ko from jsonb_to_recordset($j$[{"en":"Where are you from?","ko":"너는 어느 나라에서 왔니?"},{"en":"I'm from Korea.","ko":"나는 한국에서 왔어."},{"en":"How do you spell your name?","ko":"너의 이름은 철자가 어떻게 되니?"},{"en":"H-A-N-A.","ko":"H-A-N-A야."},{"en":"Nice to meet you.","ko":"만나서 반가워."},{"en":"My name is Hana.","ko":"내 이름은 하나야."}]$j$::jsonb) as x(en text, ko text) on conflict (en) do nothing;
  insert into unit_expressions(unit_id, expression_id) select v_unit, e.id from expressions e where e.en in (select en from jsonb_to_recordset($j$[{"en":"Where are you from?","ko":"너는 어느 나라에서 왔니?"},{"en":"I'm from Korea.","ko":"나는 한국에서 왔어."},{"en":"How do you spell your name?","ko":"너의 이름은 철자가 어떻게 되니?"},{"en":"H-A-N-A.","ko":"H-A-N-A야."},{"en":"Nice to meet you.","ko":"만나서 반가워."},{"en":"My name is Hana.","ko":"내 이름은 하나야."}]$j$::jsonb) as x(en text)) on conflict do nothing;

  -- 문항
  create temp table _l1 on commit drop as select * from jsonb_to_recordset($j$[{"lesson":1,"pos":0,"n":0,"kind":"goal","tag":"expr","payload":{"tag":"expr","pic":"france","k":"goal","title":"나라와 이름의 철자를 묻고 답할 수 있어요.","items":[{"en":"Where are you from?","ko":"너는 어느 나라에서 왔니?","group":"출신 국가 묻고 답하기"},{"en":"I'm from France.","ko":"나는 프랑스에서 왔어.","group":"출신 국가 묻고 답하기"},{"en":"How do you spell your name?","ko":"너의 이름은 철자가 어떻게 되니?","group":"이름의 철자 묻고 답하기"},{"en":"H-A-N-A.","ko":"H-A-N-A야.","group":"이름의 철자 묻고 답하기"}]}},{"lesson":1,"pos":1,"n":0,"kind":"lecture","tag":"expr","payload":{"tag":"expr","k":"lecture","title":"Lesson 1","slides":[{"head":"새로 만난 친구에게 이렇게 말해요","text":["새 친구를 만나면 어느 나라에서 왔는지 궁금해요.","이번 Lesson에서는 [[출신 나라]]와 [[이름의 철자]]를 묻고 대답하는 말을 배워요."],"pic":"france","cards":["Where are you from? | 너는 어느 나라에서 왔니? | 묻는 말","I'm from France. | 나는 프랑스에서 왔어. | 대답"]},{"head":"출신 나라 묻고 답하기","text":["어느 나라에서 왔는지 물을 때는 [[Where are you from?]]이라고 해요.","대답은 [[I'm from]] 뒤에 나라 이름을 붙여요."],"pic":"korea","cards":["Where are you from? | 너는 어느 나라에서 왔니?","I'm from Korea. | 나는 한국에서 왔어."],"formula":["{{Where}} + are + you + from?","I'm + from + 나라 이름."],"tip":"나라 이름은 항상 [[대문자]]로 시작해요. (Korea, Brazil, Egypt)"},{"head":"나라 이름 알아 두기","text":["이번 Lesson에서 만나는 나라들이에요."],"table":["영어 | 우리말","Brazil | 브라질","Egypt | 이집트","France | 프랑스","Korea | 한국","Thailand | 태국","the U.S. | 미국"],"tip":"미국은 [[I'm from the U.S.]]처럼 앞에 [[the]]를 붙여 말해요."},{"head":"이름의 철자 묻고 답하기","text":["이름을 어떻게 쓰는지 물을 때는 [[How do you spell your name?]]이라고 해요.","대답은 알파벳을 하나씩 읽어요. 글자 사이에 짧게 쉬어요."],"pic":"brazil","cards":["How do you spell your name? | 너의 이름은 철자가 어떻게 되니? | 묻는 말","L-E-O. | L-E-O야. | 대답"],"formula":["How + do + you + {{spell}} + your name?","H-A-N-A."],"tip":"내 이름은 [[My name is Hana.]] 또는 [[I'm Hana.]]라고 소개해요."},{"head":"정리해요","text":["묻는 말과 대답을 짝지어 기억해요."],"table":["묻는 말 | 대답","Where are you from? | I'm from Egypt.","How do you spell your name? | A-M-I-R."],"tip":"질문을 들으면 [[어느 나라]]인지, [[이름 철자]]인지 먼저 생각해요."}]}},{"lesson":1,"pos":2,"n":0,"kind":"vcards","tag":"vocab","payload":{"tag":"vocab","k":"vcards","words":["brazil","egypt","france","korea","thailand","us"]}},{"lesson":1,"pos":3,"n":0,"kind":"wrepeat","tag":"vocab","payload":{"tag":"vocab","k":"wrepeat","words":["brazil","egypt","france","korea","thailand","us"]}},{"lesson":1,"pos":4,"n":0,"kind":"wchoice","tag":"vocab","payload":{"tag":"vocab","k":"wchoice","word":"brazil","dir":"en2ko","wrong":["이집트","프랑스","태국"]}},{"lesson":1,"pos":4,"n":1,"kind":"wchoice","tag":"vocab","payload":{"tag":"vocab","k":"wchoice","word":"france","dir":"en2ko","wrong":["한국","브라질","미국"]}},{"lesson":1,"pos":4,"n":2,"kind":"wchoice","tag":"vocab","payload":{"tag":"vocab","k":"wchoice","word":"thailand","dir":"en2ko","wrong":["이집트","한국","프랑스"]}},{"lesson":1,"pos":4,"n":3,"kind":"wchoice","tag":"vocab","payload":{"tag":"vocab","k":"wchoice","word":"egypt","dir":"ko2en","wrong":["Brazil","France","Korea"]}},{"lesson":1,"pos":4,"n":4,"kind":"wchoice","tag":"vocab","payload":{"tag":"vocab","k":"wchoice","word":"korea","dir":"ko2en","wrong":["Thailand","Egypt","France"]}},{"lesson":1,"pos":4,"n":5,"kind":"wchoice","tag":"vocab","payload":{"tag":"vocab","k":"wchoice","word":"us","dir":"ko2en","wrong":["Brazil","Thailand","Korea"]}},{"lesson":1,"pos":5,"n":0,"kind":"kexp","tag":"expr","payload":{"tag":"expr","k":"kexp","items":[{"en":"Where are you from?","ko":"너는 어느 나라에서 왔니?","label":"출신 나라를 묻는 말"},{"en":"I'm from Egypt.","ko":"나는 이집트에서 왔어.","label":"출신 나라를 말하는 대답"},{"en":"How do you spell your name?","ko":"너의 이름은 철자가 어떻게 되니?","label":"이름의 철자를 묻는 말"},{"en":"A-M-I-R.","ko":"A-M-I-R이야.","label":"철자를 말하는 대답"}]}},{"lesson":1,"pos":6,"n":0,"kind":"sdrill","tag":"speak","payload":{"tag":"speak","pic":"brazil","k":"sdrill","tpl":"I'm from {}.","words":["Brazil","Egypt","France","Korea"]}},{"lesson":1,"pos":6,"n":1,"kind":"sdrill","tag":"speak","payload":{"tag":"speak","pic":"thailand","k":"sdrill","tpl":"Where are you from, {}?","words":["Hana","Leo","Chloe","Tom"]}},{"lesson":1,"pos":6,"n":2,"kind":"sdrill","tag":"speak","payload":{"tag":"speak","pic":"korea","k":"sdrill","tpl":"My name is {}.","words":["Hana","Leo","Chloe","Amir"]}},{"lesson":1,"pos":6,"n":3,"kind":"sdrill","tag":"speak","payload":{"tag":"speak","pic":"france","k":"sdrill","tpl":"{}.","words":["H-A-N-A","L-E-O","T-O-M","K-A-I"]}},{"lesson":1,"pos":7,"n":0,"kind":"scene","tag":"listen","payload":{"tag":"listen","pic":"france","k":"scene","title":"세계 친구들 캠프 ①","scenes":[{"who":"Ms. Green","en":"Welcome to World Friends Camp!","ko":"세계 친구들 캠프에 온 걸 환영해요!"},{"who":"Ms. Green","en":"Let's say hello to our new friends.","ko":"새 친구들에게 인사해요."},{"who":"Hana","en":"Hello. My name is Hana.","ko":"안녕. 내 이름은 하나야."},{"who":"Hana","en":"Nice to meet you.","ko":"만나서 반가워."},{"who":"Leo","en":"Hi, I'm Leo.","ko":"안녕, 나는 레오야."},{"who":"Leo","en":"Nice to meet you, too.","ko":"나도 만나서 반가워."},{"who":"Hana","en":"Where are you from, Leo?","ko":"레오, 너는 어느 나라에서 왔니?"},{"who":"Leo","en":"I'm from Brazil.","ko":"나는 브라질에서 왔어."},{"who":"Leo","en":"Where are you from, Chloe?","ko":"클로이, 너는 어느 나라에서 왔니?"},{"who":"Chloe","en":"I'm from France.","ko":"나는 프랑스에서 왔어."},{"who":"Tom","en":"Hi, I'm Tom. I'm from the U.S.","ko":"안녕, 나는 톰이야. 나는 미국에서 왔어."},{"who":"Ms. Green","en":"Welcome, everyone!","ko":"모두 환영해요!"}],"sub":"en","explain":["[[Where are you from?]]은 \"너는 어느 나라에서 왔니?\"라고 묻는 말이에요.","대답은 [[I'm from]] 뒤에 나라 이름을 붙여요. (I'm from Brazil.)","미국은 [[I'm from the U.S.]]처럼 the 를 붙여 말해요.","\"Welcome to … (…에 온 걸 환영해요)\", \"Let's say hello (인사해요)\"는 이 장면에서만 나오는 말이에요. 뜻만 알아 두세요."],"review":true,"replay":2,"qs":[{"t":"mc","q":"레오가 \"I'm from Brazil.\"이라고 말한 뜻은 무엇인가요?","ans":"나는 브라질에서 왔어.","wrong":["나는 프랑스에서 왔어.","나는 레오야."]},{"t":"mc","q":"클로이는 어느 나라에서 왔나요?","ans":"프랑스","wrong":["브라질","미국"]},{"t":"mc","q":"톰은 어느 나라에서 왔나요?","ans":"미국","wrong":["한국","이집트"]}]}},{"lesson":1,"pos":8,"n":0,"kind":"scene","tag":"listen","payload":{"tag":"listen","pic":"egypt","k":"scene","title":"새로 온 친구","scenes":[{"who":"Mr. Brown","en":"Good morning, class.","ko":"좋은 아침이에요, 여러분."},{"who":"Mr. Brown","en":"We have a new friend today.","ko":"오늘 새 친구가 왔어요."},{"who":"Amir","en":"Hello. I'm Amir.","ko":"안녕. 나는 아미르야."},{"who":"Amir","en":"Nice to meet you all.","ko":"모두 만나서 반가워."},{"who":"Hana","en":"Hi, Amir. Where are you from?","ko":"안녕, 아미르. 너는 어느 나라에서 왔니?"},{"who":"Amir","en":"I'm from Egypt.","ko":"나는 이집트에서 왔어."},{"who":"Leo","en":"Cool!","ko":"멋지다!"},{"who":"Mr. Brown","en":"How do you spell your name?","ko":"이름의 철자가 어떻게 되니?"},{"who":"Amir","en":"A-M-I-R.","ko":"A-M-I-R이에요."},{"who":"Mr. Brown","en":"Welcome, Amir.","ko":"환영해요, 아미르."}],"sub":"en","explain":["[[Nice to meet you all.]]은 여러 명에게 \"모두 만나서 반가워.\"라고 인사하는 말이에요.","이름의 철자는 [[How do you spell your name?]]으로 묻고, 알파벳을 하나씩 읽어 대답해요. (A-M-I-R.)","[[Where are you from?]]에는 [[I'm from]] 뒤에 나라 이름을 붙여 대답해요.","\"Good morning(좋은 아침)\", \"We have a new friend(새 친구가 왔어요)\", \"Cool!(멋지다!)\"은 이 장면에서만 나오는 말이에요. 뜻만 알아 두세요."],"review":true,"replay":2,"qs":[{"t":"mc","q":"아미르는 어느 나라에서 왔나요?","ans":"이집트","wrong":["태국","브라질"]},{"t":"mc","q":"선생님이 \"How do you spell your name?\"이라고 물은 뜻은 무엇인가요?","ans":"이름의 철자가 어떻게 되니?","wrong":["너는 어느 나라에서 왔니?","만나서 반가워."]},{"t":"mc","q":"아미르의 이름 철자는 무엇인가요?","ans":"A-M-I-R","wrong":["A-M-Y","A-N-I-R"]}]}},{"lesson":1,"pos":9,"n":0,"kind":"lchpic","tag":"listen","payload":{"tag":"listen","q":"어느 나라에서 왔다고 말하고 있나요?","say":"Teacher(woman): Where are you from?\nHana(girl): I'm from Korea.","replay":2,"opts":[{"t":"korea","flag":"korea"},{"t":"brazil","flag":"brazil"},{"t":"egypt","flag":"egypt"},{"t":"france","flag":"france"}],"a":0,"k":"lchpic"}},{"lesson":1,"pos":9,"n":1,"kind":"lchpic","tag":"listen","payload":{"tag":"listen","q":"어느 나라에서 왔다고 말하고 있나요?","say":"Chloe(girl): Hi, I'm Chloe.\nTom(boy): Where are you from?\nChloe(girl): I'm from France.","replay":2,"opts":[{"t":"thailand","flag":"thailand"},{"t":"france","flag":"france"},{"t":"korea","flag":"korea"},{"t":"us","flag":"us"}],"a":1,"k":"lchpic"}},{"lesson